import React, { useState, useEffect } from 'react';
import {
    Container,
    Typography,
    Paper,
    Box,
    Grid,
    Card,
    CardContent,
    Divider,
    CircularProgress,
    Alert,
    Tabs,
    Tab,
    TextField,
    Button,
    IconButton
} from '@mui/material';
import { usePrayerTimes } from '../contexts/PrayerTimesContext';
import prayerTimesService from '../services/prayerTimesService';
import HijriCalendar from '../components/prayer-times/HijriCalendar';
import CalendarMonthIcon from '@mui/icons-material/CalendarMonth';
import DateRangeIcon from '@mui/icons-material/DateRange';
import NavigateNextIcon from '@mui/icons-material/NavigateNext';
import NavigateBeforeIcon from '@mui/icons-material/NavigateBefore';
import TodayIcon from '@mui/icons-material/Today';
import EventNoteIcon from '@mui/icons-material/EventNote';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import { Helmet } from 'react-helmet-async';
import { useTranslation } from 'react-i18next';

const CalendarPage = () => {
    const { t, i18n } = useTranslation(['calendar', 'prayerTimes']);
    const lang = i18n.resolvedLanguage || 'en';
    const P = (name) => t(`prayerTimes:prayers.${name}`);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [calendar, setCalendar] = useState(null);
    const [month, setMonth] = useState(new Date().getMonth() + 1); // 1-12
    const [year, setYear] = useState(new Date().getFullYear());
    const [tabValue, setTabValue] = useState(0);
    const [viewType, setViewType] = useState('month'); // 'month' or 'year'

    const { params } = usePrayerTimes();

    // Handle tab change
    const handleTabChange = (event, newValue) => {
        setTabValue(newValue);
    };

    const handleMonthChange = (newMonth) => {
        if (newMonth < 1) {
            setYear(year - 1);
            setMonth(12);
        } else if (newMonth > 12) {
            setYear(year + 1);
            setMonth(1);
        } else {
            setMonth(newMonth);
        }
    };

    // Reset to current month
    const handleResetToCurrentDate = () => {
        const now = new Date();
        setMonth(now.getMonth() + 1);
        setYear(now.getFullYear());
    };

    // Fetch calendar data when params, month or year changes
    useEffect(() => {
        const fetchCalendar = async () => {
            if (!params.latitude || !params.longitude) return;

            setLoading(true);
            setError(null);

            try {
                const calendarParams = {
                    latitude: params.latitude,
                    longitude: params.longitude,
                    method: params.method,
                    school: params.school,
                    latitudeAdjustmentMethod: params.latitudeAdjustmentMethod,
                    midnightMode: params.midnightMode
                };

                let response;
                try {
                    if (viewType === 'month') {
                        // Fetch monthly calendar
                        response = await prayerTimesService.getMonthlyPrayerTimes(year, month, calendarParams);
                    } else {
                        // Fetch yearly calendar
                        response = await prayerTimesService.getYearlyPrayerTimes(year, calendarParams);
                    }

                    if (response.code === 200) {
                        if (viewType === 'month') {
                            // Format monthly response
                            const formattedCalendar = {
                                viewType: 'month',
                                months: {
                                    gregorian: {
                                        name: response.data.monthName || new Date(year, month - 1, 1).toLocaleString(lang, { month: 'long' }),
                                        number: response.data.month
                                    },
                                    hijri: {
                                        name: t('title'),
                                        number: ""
                                    }
                                },
                                days: response.data.days || [],
                                meta: response.data.meta || {}
                            };
                            setCalendar(formattedCalendar);
                        } else {
                            // Format yearly response
                            const formattedCalendar = {
                                viewType: 'year',
                                year: response.data.year,
                                months: response.data.months || [],
                                meta: response.data.meta || {}
                            };
                            setCalendar(formattedCalendar);
                        }
                    } else {
                        console.warn('API returned non-200 status:', response.status);
                        // Set a minimal calendar object to prevent UI errors
                        setCalendar({
                            viewType: viewType,
                            months: {
                                gregorian: {
                                    name: new Date(year, month - 1, 1).toLocaleString(lang, { month: 'long' }),
                                    number: month
                                },
                                hijri: {
                                    name: t('calendarView'),
                                    number: ""
                                }
                            }
                        });
                    }
                } catch (apiError) {
                    console.error('Calendar API error:', apiError);
                    // Fallback calendar object
                    setCalendar({
                        viewType: viewType,
                        months: {
                            gregorian: {
                                name: new Date(year, month - 1, 1).toLocaleString(lang, { month: 'long' }),
                                number: month
                            },
                            hijri: {
                                name: t('calendarView'),
                                number: ""
                            }
                        }
                    });
                }
            } catch (err) {
                setError(err.message || t('error'));
                console.error(err);
            } finally {
                setLoading(false);
            }
        };

        fetchCalendar();
    }, [params, month, year, viewType]); // eslint-disable-line react-hooks/exhaustive-deps

    // Render prayer times for a specific day
    const renderDayPrayerTimes = (day) => {
        if (!day.timings) return null;

        return (
            <Grid container alignItems="center">
                <Grid item xs={2}>
                    <Box sx={{ display: 'flex', flexDirection: 'column' }}>
                        <Typography variant="body1" fontWeight="medium">
                            {new Date(day.date).getDate()}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                            {day.weekday}
                        </Typography>
                        {day.hijri && (
                            <Typography variant="caption" color="text.secondary">
                                {day.hijri.day} {lang === 'ar' ? day.hijri.month?.ar : day.hijri.month?.en}
                            </Typography>
                        )}
                    </Box>
                </Grid>
                <Grid item xs={2}>
                    <Typography variant="body2">{day.timings.Fajr}</Typography>
                </Grid>
                <Grid item xs={2}>
                    <Typography variant="body2">{day.timings.Sunrise}</Typography>
                </Grid>
                <Grid item xs={2}>
                    <Typography variant="body2">{day.timings.Dhuhr}</Typography>
                </Grid>
                <Grid item xs={2}>
                    <Typography variant="body2">{day.timings.Asr}</Typography>
                </Grid>
                <Grid item xs={2}>
                    <Typography variant="body2">{day.timings.Maghrib}</Typography>
                </Grid>
            </Grid>
        );
    };

    // Render monthly calendar view
    const renderMonthlyView = () => {
        if (!calendar || !calendar.days) {
            return (
                <Box sx={{ mt: 4, p: 3, textAlign: 'center', border: '1px dashed', borderColor: 'divider', borderRadius: 2 }}>
                    <Typography variant="h6" gutterBottom>
                        {t('tabs.prayer')}
                    </Typography>
                    <Typography variant="body1" sx={{ mb: 2 }}>
                        {t('empty.month')}
                    </Typography>
                </Box>
            );
        }

        const today = new Date().toISOString().split('T')[0];

        return (
            <Box sx={{ mt: 2 }}>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <Paper sx={{ p: 2, mb: 2, bgcolor: 'primary.main', color: 'primary.contrastText' }}>
                            <Grid container>
                                <Grid item xs={2}>
                                    <Typography variant="subtitle1" fontWeight="bold">{t('date')}</Typography>
                                </Grid>
                                <Grid item xs={2}>
                                    <Typography variant="subtitle1" fontWeight="bold">{P('Fajr')}</Typography>
                                </Grid>
                                <Grid item xs={2}>
                                    <Typography variant="subtitle1" fontWeight="bold">{P('Sunrise')}</Typography>
                                </Grid>
                                <Grid item xs={2}>
                                    <Typography variant="subtitle1" fontWeight="bold">{P('Dhuhr')}</Typography>
                                </Grid>
                                <Grid item xs={2}>
                                    <Typography variant="subtitle1" fontWeight="bold">{P('Asr')}</Typography>
                                </Grid>
                                <Grid item xs={2}>
                                    <Typography variant="subtitle1" fontWeight="bold">{P('Maghrib')}</Typography>
                                </Grid>
                            </Grid>
                        </Paper>
                    </Grid>

                    {calendar.days.map((day, index) => (
                        <Grid item xs={12} key={day.date || index}>
                            <Paper
                                sx={{
                                    p: 2,
                                    bgcolor: day.date === today ? 'action.selected' : 'background.paper'
                                }}
                                elevation={day.date === today ? 3 : 1}
                            >
                                {renderDayPrayerTimes(day)}
                            </Paper>
                        </Grid>
                    ))}
                </Grid>
            </Box>
        );
    };

    // Update the renderYearlyView function to handle simplified responses
    const renderYearlyView = () => {
        if (!calendar || !calendar.months) {
            return (
                <Box sx={{ mt: 4, p: 3, textAlign: 'center', border: '1px dashed', borderColor: 'divider', borderRadius: 2 }}>
                    <Typography variant="h6" gutterBottom>
                        {t('empty.yearTitle')}
                    </Typography>
                    <Typography variant="body1" sx={{ mb: 2 }}>
                        {t('empty.year')}
                    </Typography>
                </Box>
            );
        }

        return (
            <Box sx={{ mt: 2 }}>
                <Typography variant="h5" gutterBottom sx={{ mb: 3 }}>
                    {t('year.overview', { year })}
                    {calendar.isSimplified && (
                        <Typography component="span" variant="body2" color="text.secondary" sx={{ marginInlineStart: 2 }}>
                            {t('year.previewMode')}
                        </Typography>
                    )}
                </Typography>

                {calendar.isSimplified && (
                    <Alert severity="info" sx={{ mt: 1, mb: 3 }}>
                        {t('year.previewNote')}
                    </Alert>
                )}

                <Grid container spacing={3}>
                    {Array.isArray(calendar.months) && calendar.months.map((monthData, idx) => (
                        <Grid item xs={12} md={6} lg={4} key={`month-${idx}`}>
                            <Paper sx={{ p: 2, height: '100%' }}>
                                <Typography variant="h6" color="primary" gutterBottom>
                                    {monthData.monthName}
                                </Typography>

                                <Button
                                    variant="outlined"
                                    size="small"
                                    onClick={() => {
                                        setMonth(monthData.month);
                                        setViewType('month');
                                    }}
                                    startIcon={<CalendarMonthIcon />}
                                    sx={{ mb: 2 }}
                                >
                                    {t('year.details')}
                                </Button>

                                {monthData.error ? (
                                    <Typography variant="body2" color="error">
                                        {monthData.error}
                                    </Typography>
                                ) : (
                                    <>
                                        <Typography variant="body2" color="text.secondary" paragraph>
                                            {t('year.daysAvailable', { count: monthData.days?.length || 0 })}
                                            {monthData.isPreview && ` ${t('year.preview')}`}
                                        </Typography>

                                        {monthData.days && monthData.days.length > 0 && (
                                            <Box sx={{ mt: 1 }}>
                                                <Typography variant="body2" gutterBottom>
                                                    <strong>{monthData.isPreview ? t('year.sampleFirst') : t('year.sample')}</strong>
                                                </Typography>
                                                <Box sx={{ paddingInlineStart: 2, borderInlineStart: '2px solid', borderColor: 'primary.main', marginInlineStart: 1 }}>
                                                    <Typography variant="caption" display="block">
                                                        {P('Fajr')}: {monthData.days[0].timings?.Fajr}
                                                    </Typography>
                                                    <Typography variant="caption" display="block">
                                                        {P('Dhuhr')}: {monthData.days[0].timings?.Dhuhr}
                                                    </Typography>
                                                    <Typography variant="caption" display="block">
                                                        {P('Asr')}: {monthData.days[0].timings?.Asr}
                                                    </Typography>
                                                    <Typography variant="caption" display="block">
                                                        {P('Maghrib')}: {monthData.days[0].timings?.Maghrib}
                                                    </Typography>
                                                    <Typography variant="caption" display="block">
                                                        {P('Isha')}: {monthData.days[0].timings?.Isha}
                                                    </Typography>
                                                </Box>
                                            </Box>
                                        )}
                                    </>
                                )}
                            </Paper>
                        </Grid>
                    ))}
                </Grid>
            </Box>
        );
    };

    if (loading) {
        return (
            <Container maxWidth="lg" sx={{ py: 4, textAlign: 'center' }}>
                <CircularProgress size={60} />
                <Typography variant="h6" sx={{ mt: 2, color: 'text.secondary' }}>
                    {t('loading')}
                </Typography>
            </Container>
        );
    }

    return (
        <Container maxWidth="lg" sx={{ py: 4 }}>
            <Helmet>
                <title>{t('meta.title')}</title>
                <meta name="description" content={t('meta.description')} />
                <meta property="og:title" content={t('meta.title')} />
                <meta property="og:description" content={t('meta.description')} />
            </Helmet>
            <Typography variant="h4" component="h1" gutterBottom sx={{ mb: 4, color: 'primary.main', fontWeight: 500 }}>
                {t('title')}
            </Typography>

            {error && (
                <Alert severity="error" sx={{ mb: 3 }}>
                    {error}
                </Alert>
            )}

            {!params.latitude && !params.longitude && (
                <Paper sx={{ p: 4, textAlign: 'center' }}>
                    <Typography variant="h6" color="textSecondary" gutterBottom>
                        {t('noLocation.title')}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                        {t('noLocation.body')}
                    </Typography>
                </Paper>
            )}

            {params.latitude && params.longitude && (
                <Box sx={{ width: '100%' }}>
                    <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
                        <Tabs
                            value={tabValue}
                            onChange={handleTabChange}
                            aria-label={t('tabs.aria')}
                            centered
                        >
                            <Tab
                                icon={<DateRangeIcon />}
                                iconPosition="start"
                                label={t('tabs.hijri')}
                                id="tab-0"
                                aria-controls="tabpanel-0"
                            />
                            <Tab
                                icon={<CalendarMonthIcon />}
                                iconPosition="start"
                                label={t('tabs.prayer')}
                                id="tab-1"
                                aria-controls="tabpanel-1"
                            />
                        </Tabs>
                    </Box>

                    {/* Hijri Calendar Tab */}
                    <Box
                        role="tabpanel"
                        hidden={tabValue !== 0}
                        id="tabpanel-0"
                        aria-labelledby="tab-0"
                    >
                        {tabValue === 0 && <HijriCalendar />}
                    </Box>

                    {/* Prayer Times Calendar Tab */}
                    <Box
                        role="tabpanel"
                        hidden={tabValue !== 1}
                        id="tabpanel-1"
                        aria-labelledby="tab-1"
                    >
                        {tabValue === 1 && (
                            <Box>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
                                    {/* View Type Toggle */}
                                    <Box>
                                        <Button
                                            variant={viewType === 'month' ? 'contained' : 'outlined'}
                                            onClick={() => setViewType('month')}
                                            startIcon={<CalendarMonthIcon />}
                                            sx={{ marginInlineEnd: 1 }}
                                        >
                                            {t('month')}
                                        </Button>
                                        <Button
                                            variant={viewType === 'year' ? 'contained' : 'outlined'}
                                            onClick={() => setViewType('year')}
                                            startIcon={<EventNoteIcon />}
                                        >
                                            {t('yearBtn')}
                                        </Button>
                                    </Box>

                                    {/* Date Navigation and Reset */}
                                    <Box>
                                        <Button
                                            variant="outlined"
                                            startIcon={<TodayIcon />}
                                            onClick={handleResetToCurrentDate}
                                            sx={{ marginInlineStart: 2 }}
                                        >
                                            {t('today')}
                                        </Button>
                                    </Box>
                                </Box>

                                {/* Month/Year Selection Controls */}
                                <Paper sx={{ p: 3, mb: 4, bgcolor: 'background.default' }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                            {viewType === 'month' && (
                                                <>
                                                    <IconButton
                                                        onClick={() => handleMonthChange(month - 1)}
                                                        aria-label={t('aria.prevMonth')}
                                                    >
                                                        <NavigateBeforeIcon />
                                                    </IconButton>

                                                    <LocalizationProvider dateAdapter={AdapterDateFns}>
                                                        <DatePicker
                                                            views={['year', 'month']}
                                                            label={t('yearMonth')}
                                                            minDate={new Date('2000-01-01')}
                                                            maxDate={new Date('2050-12-31')}
                                                            value={new Date(year, month - 1)}
                                                            onChange={(newDate) => {
                                                                if (newDate) {
                                                                    setYear(newDate.getFullYear());
                                                                    setMonth(newDate.getMonth() + 1);
                                                                }
                                                            }}
                                                            renderInput={(params) => <TextField {...params} variant="standard" helperText={null} />}
                                                            sx={{ mx: 2, width: 170 }}
                                                        />
                                                    </LocalizationProvider>

                                                    <IconButton
                                                        onClick={() => handleMonthChange(month + 1)}
                                                        aria-label={t('aria.nextMonth')}
                                                    >
                                                        <NavigateNextIcon />
                                                    </IconButton>
                                                </>
                                            )}

                                            {viewType === 'year' && (
                                                <>
                                                    <IconButton
                                                        onClick={() => setYear(year - 1)}
                                                        aria-label={t('aria.prevYear')}
                                                    >
                                                        <NavigateBeforeIcon />
                                                    </IconButton>

                                                    <LocalizationProvider dateAdapter={AdapterDateFns}>
                                                        <DatePicker
                                                            views={['year']}
                                                            label={t('yearBtn')}
                                                            minDate={new Date('2000-01-01')}
                                                            maxDate={new Date('2050-12-31')}
                                                            value={new Date(year, 0)}
                                                            onChange={(newDate) => {
                                                                if (newDate) {
                                                                    setYear(newDate.getFullYear());
                                                                }
                                                            }}
                                                            renderInput={(params) => <TextField {...params} variant="standard" helperText={null} />}
                                                            sx={{ mx: 2, width: 170 }}
                                                        />
                                                    </LocalizationProvider>

                                                    <IconButton
                                                        onClick={() => setYear(year + 1)}
                                                        aria-label={t('aria.nextYear')}
                                                    >
                                                        <NavigateNextIcon />
                                                    </IconButton>
                                                </>
                                            )}
                                        </Box>

                                        {/* Calendar Info */}
                                        <Box sx={{ textAlign: 'end' }}>
                                            <Typography variant="h5" gutterBottom>
                                                {viewType === 'month'
                                                    ? `${calendar?.months?.gregorian?.name || new Date(year, month - 1).toLocaleString(lang, { month: 'long' })} ${year}`
                                                    : t('year.calendar', { year })
                                                }
                                            </Typography>
                                            {calendar?.meta && (
                                                <Typography variant="body2" color="text.secondary">
                                                    {t('methodLine', { method: calendar.meta.method?.name || 'ISNA', school: calendar.meta.school || t('standard') })}
                                                </Typography>
                                            )}
                                        </Box>
                                    </Box>
                                </Paper>

                                {/* Calendar Content */}
                                {viewType === 'month' ? renderMonthlyView() : renderYearlyView()}
                            </Box>
                        )}
                    </Box>
                </Box>
            )}
        </Container>
    );
};

export default CalendarPage;